import type { Config } from "jest";
import nextJest from "next/jest";

const createJestConfig = nextJest({
  // Path to the Next.js app
  dir: "./",
});

const config: Config = {
  // Use jsdom environment for DOM testing
  testEnvironment: "jsdom",

  // Setup file run before each test suite
  setupFilesAfterSetup: ["<rootDir>/jest.setup.ts"],

  // Module name mapper for path aliases and CSS modules
  moduleNameMapper: {
    // Path aliases from tsconfig.json
    "^@/(.*)$": "<rootDir>/src/$1",
    "^@public/(.*)$": "<rootDir>/public/$1",

    // Mock CSS modules — returns a proxy object where any className lookup
    // returns the key itself (e.g. styles.foo → "foo")
    "\\.module\\.css$": "identity-obj-proxy",

    // Mock non-module CSS imports
    "\\.css$": "<rootDir>/__mocks__/styleMock.ts",
  },

  // Transform TypeScript files with ts-jest
  transform: {
    "^.+\\.(ts|tsx)$": [
      "ts-jest",
      {
        tsconfig: "tsconfig.json",
        // Use react-jsx transform for JSX
        jsx: "react-jsx",
      },
    ],
  },

  // Files to include in coverage
  collectCoverageFrom: [
    "app/**/*.{ts,tsx}",
    "!app/**/*.d.ts",
    "!app/**/__tests__/**",
  ],

  // Test file patterns
  testMatch: [
    "<rootDir>/app/**/__tests__/**/*.test.{ts,tsx}",
    "<rootDir>/app/**/*.test.{ts,tsx}",
  ],

  // Transform node_modules that need it (Next.js ESM packages)
  transformIgnorePatterns: [
    "/node_modules/(?!(next|@next)/)",
  ],

  // Clear mocks between tests
  clearMocks: true,
};

export default createJestConfig(config);
